sys_script.script:
(function executeRule(current, previous) {

    // BR-TASK-03
    // Active Clinical Task requires a future Due Date/Time.

    // Check Active correctly.
    if (current.getValue('active') != '1') {
        return;
    }

    // Due Date/Time is mandatory for an Active task.
    if (gs.nil(current.getValue('due_date'))) {

        gs.addErrorMessage(
            'Due Date is required for an Active Clinical Task.'
        );

        current.setAbortAction(true);
        return;
    }

    // Convert the Date/Time field to GlideDateTime.
    var dueDateTime = new GlideDateTime(
        current.getValue('due_date')
    );

    // Get current server Date/Time.
    var nowDateTime = new GlideDateTime();

    // Compare the actual Date/Time values.
    // Numeric comparison avoids date-string/time-zone issues.
    if (dueDateTime.getNumericValue() <= nowDateTime.getNumericValue()) {

        gs.addErrorMessage(
            'Due Date for an Active Clinical Task must be in the future.'
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
